/* PracticeIELTS: standalone interface demo. No server, account system or AI service. */
(() => {
  'use strict';
  const KEY = 'practiceielts.interface-demo.v1';
  const paths = {
    headphones:'M3 14v-3a9 9 0 0 1 18 0v3M3 13H2v7h4v-7H3m18 0h1v7h-4v-7h3',
    home:'m3 10 9-7 9 7M5 9v12h5v-7h4v7h5V9',
    library:'M4 3v18m4-18v18M12 4l4-1 5 17-4 1-5-17',
    file:'M14 2H5v20h14V7l-5-5Zm0 0v6h5M8 12h8m-8 4h6',
    book:'M12 5C8 2 4 3 2 4v16c4-2 7-1 10 1 3-2 6-3 10-1V4c-3-1-6-2-10 1Zm0 0v16',
    chart:'M4 21v-7m5 7V9m5 12V5m5 16V2',
    settings:'m9 3 1-2h4l1 2 3 2 2 1v4l-2 1-1 3-1 2h-4l-1-2-3-1-2-1v-4l2-1 1-3Z M14 8a3 3 0 1 0 0 6 3 3 0 0 0 0-6',
    search:'m21 21-5-5M18 10a8 8 0 1 0-16 0 8 8 0 0 0 16 0',
    chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',
    clock:'M12 8v5l3 2M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',
    target:'M21 12a9 9 0 1 1-9-9m0 5a4 4 0 1 0 4 4m-4 0 10-10m-4 0h4v4',
    wave:'M3 9v6m4-10v14m5-18v22m5-19v16m4-12v8',
    play:'m8 5 11 7-11 7V5',pause:'M8 5v14m8-14v14',replay:'M3 10a9 9 0 1 1 1 8M3 4v6h6',
    rewind:'m12 5-9 7 9 7V5m9 0-9 7 9 7V5',forward:'m3 5 9 7-9 7V5m9 0 9 7-9 7V5',
    volume:'m11 4-6 5H2v6h3l6 5V4m4 4a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',
    check:'m4 12 5 5L20 6',checks:'m2 12 5 5L18 6m-6 11 3 3 8-10',
    light:'M8 16a7 7 0 1 1 8 0v3H8v-3m1 6h6',
    eye:'M2 12s4-8 10-8 10 8 10 8-4 8-10 8S2 12 2 12Zm13 0a3 3 0 1 0-6 0 3 3 0 0 0 6 0',
    plus:'M12 4v16M4 12h16',upload:'M12 16V2m-5 5 5-5 5 5M3 15v6h18v-6',
    shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6l9-4Zm-5 10 3 3 7-7',
    lock:'M5 10h14v11H5V10m3 0V6a4 4 0 0 1 8 0v4',menu:'M3 6h18M3 12h18M3 18h18',
    spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7',
    speech:'M21 4H3v13h4v5l6-5h8V4M7 8h10m-10 4h7',
    pen:'m4 16-1 5 5-1L21 7l-5-5L4 16Zm10-12 5 5',
    folder:'M2 6h8l2 3h10v12H2V6',close:'m5 5 14 14M19 5 5 19',
    info:'M12 11v6m0-10v.1M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',
    mail:'M2 4h20v16H2V4m0 0 10 9 10-9',
  };
  const icon = (name,cls='') => `<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
  const esc = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const norm = text => String(text).normalize('NFKC').toLowerCase().replace(/’/g,"'").replace(/[^\p{L}\p{N}'\s]/gu,' ').trim().replace(/\s+/g,' ');
  const words = text => norm(text).split(' ').filter(Boolean);
  const fmt = ms => `${Math.floor(Math.max(0,ms)/60000)}:${String(Math.floor(Math.max(0,ms)/1000)%60).padStart(2,'0')}`;
  const initial = () => ({role:'student',materials:[structuredClone(window.DEMO_MATERIAL)],sessions:{},checks:[],attempts:{},last:null});
  let state;
  try { state=JSON.parse(localStorage.getItem(KEY))||initial(); if(!Array.isArray(state.materials))state=initial(); } catch {state=initial();}
  function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Brauzer xotirasi to‘ldi. Oxirgi o‘zgarishlarni saqlab bo‘lmadi.');}}
  let toastTimer;
  function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3600);}
  const root=document.querySelector('#app');
  const audio=document.querySelector('#player');
  const sourceCache=new Map();
  let activeAudio=null, audioVersion=0, audioFrame=0, routeInfo=[], timerInterval, processingTimer;
  let libraryFilter='', searchTerm='', drawer=false, draftForm=null, uploadChoice=null;
  const names={easy:'Oson',medium:'O‘rta',hard:'Murakkab'};
  const descriptions={easy:'Qisqa chunk yoki gap · so‘zlar soni ko‘rinadi',medium:'Bitta to‘liq gap · so‘zlar soni yashirilgan',hard:'2–3 gap uzluksiz · tinglab yozib boring'};
  const futureModules=[['reading','Reading','book','Matnni o‘qish va savollar bilan ishlash.'],['writing','Writing','pen','Yozish ko‘nikmasi uchun alohida makon.'],['speaking','Speaking','speech','Gapirish va fikringizni ifodalash.']];
  function getMaterial(id){const m=state.materials.find(x=>x.id===id);return m&&(state.role==='admin'||m.status==='published')?m:null;}
  const published=()=>state.materials.filter(m=>m.status==='published');
  const sid=(id,mode)=>id+'|'+mode;
  function session(id,mode){const key=sid(id,mode);if(!state.sessions[key])state.sessions[key]={index:0,answers:{},results:{}};return state.sessions[key];}
  function groups(m,mode){if(mode==='easy')return m.chunks;if(mode==='medium')return m.sentences;const out=[];for(let p=1;p<=m.parts.length;p++){const part=m.sentences.filter(s=>s.part===p);for(let i=0;i<part.length;i+=3){const list=part.slice(i,i+3);if(list.length)out.push({part:p,text:list.map(s=>s.text).join(' '),start:list[0].start,end:list.at(-1).end});}}return out;}
  const badge=(text,kind='',name='')=>`<span class="badge ${kind}">${name?icon(name):''}${esc(text)}</span>`;
  const btn=(text,href,kind='primary',name='chevron')=>`<a class="btn ${kind}" href="${esc(href)}">${esc(text)}${icon(name)}</a>`;
  const book=(mini=false)=>`<div class="book ${mini?'mini':''}" aria-hidden="true"><small>PracticeIELTS</small><strong>LISTEN<br>& LEARN</strong><em>01</em><span>ONE SENTENCE AT A TIME</span></div>`;
  const wave=()=>`<div class="wave" aria-hidden="true">${[12,28,22,41,29,57,34,73,51,31,17,38,24,19,47,32,49,23,17,10].map(h=>`<i style="height:${h}px"></i>`).join('')}</div>`;
  const section=(title,href='',label='Barchasi')=>`<div class="section-head"><h2>${esc(title)}</h2>${href?`<a class="link" href="${esc(href)}">${esc(label)}${icon('chevron')}</a>`:''}</div>`;
  const head=(title,description,eyebrow='',action='')=>`<div class="page-head"><div>${eyebrow?`<div class="eyebrow">${esc(eyebrow)}</div>`:''}<h1>${esc(title)}</h1><p>${esc(description)}</p></div>${action}</div>`;
  const empty=(title,text,action='')=>`<section class="card empty"><span class="tile-icon">${icon('book')}</span><h2>${esc(title)}</h2><p>${esc(text)}</p>${action}</section>`;
  const crumbs=(m,last)=>`<div class="breadcrumbs"><a href="#dashboard">Bosh sahifa</a>${icon('chevron')}<a href="#library">Kutubxona</a>${m?`${icon('chevron')}<a href="#material/${esc(m.id)}">${esc(m.title)}</a>`:''}${last?`${icon('chevron')}<span>${esc(last)}</span>`:''}</div>`;
  function shell(content){const admin=state.role==='admin',path=routeInfo[0]||'dashboard';const nav=admin?[['admin','Umumiy ko‘rinish','home'],['admin/materials','Mock materiallari','library'],['admin/new','Yangi mock qo‘shish','plus']]:[['dashboard','Bosh sahifa','home'],['library','Practice Library','library'],['library/practice','Listening Practice','headphones'],['library/mock','Mock testlar','file'],['mistakes','Xatolarim','book'],['progress','Natijalarim','chart']];const current=routeInfo.join('/');
  return `<header class="topbar"><button class="mobile-menu" data-action="drawer" aria-label="Menyuni ochish">${icon('menu')}</button><a class="brand" href="#${admin?'admin':'dashboard'}">${icon('headphones')}<span>Practice<b>IELTS</b></span><small class="demo-tag">DEMO</small></a><form class="global-search" id="global-search">${icon('search')}<input name="search" aria-label="Material qidirish" placeholder="Test, mavzu yoki kalit so‘zni qidiring…" value="${esc(searchTerm)}"></form><div class="header-right"><div class="role-switch" aria-label="Demo ko‘rinishi"><button data-action="role" data-role="student" class="${!admin?'active':''}" aria-pressed="${!admin}">O‘quvchi</button><button data-action="role" data-role="admin" class="${admin?'active':''}" aria-pressed="${admin}">Admin</button></div><div class="profile"><span class="avatar">${admin?'AD':'AB'}</span><span>${admin?'Administrator':'Abdulaziz'}</span>${icon('down')}</div></div></header>${drawer?'<button class="backdrop" data-action="drawer" aria-label="Menyuni yopish"></button>':''}<aside class="sidebar ${drawer?'open':''}"><div class="sidebar-label">${admin?'KONTENT BOSHQARUVI':'SIZNING O‘QUV MAKONINGIZ'}</div><nav aria-label="Asosiy menyu">${nav.map(([to,label,i])=>{const active=current===to||(to==='library'&&path==='material')||(to==='library/practice'&&path==='practice')||(to==='admin/materials'&&path==='admin'&&routeInfo[1]==='review');return `<a class="${active?'active':''}" href="#${to}" ${active?'aria-current="page"':''}>${icon(i)}${esc(label)}</a>`;}).join('')}</nav><div class="soon-nav"><p>KELAJAK MODULLARI</p>${futureModules.map(([id,title,i])=>`<a href="#future/${id}">${icon(i)}${title}<span>Tez kunda</span></a>`).join('')}</div><div class="sidebar-extra"><a href="#about">${icon('info')}Demo haqida</a></div><div class="sidebar-footer">${icon('wave')}<strong>Kichik qadamlar.<br>Haqiqiy o‘sish.</strong>Bugungi mashqdan boshlang.</div></aside><main class="main">${content}<footer class="footer"><span>© ${new Date().getFullYear()} PracticeIELTS</span><span>Lokal interfeys demo · faqat shu brauzerda</span></footer></main>`;}
  function modules(){return `<div class="module-grid"><a class="card module" href="#${state.role==='admin'?'admin/materials':'library'}">${icon('headphones')}<h3>Listening</h3><p>Mock test va undan avtomatik Practice.</p>${badge('Hozir mavjud','green','check')}</a>${futureModules.map(([id,title,i,text])=>`<a class="card module future" href="#future/${id}">${icon(i)}<h3>${title}</h3><p>${esc(text)}</p>${badge('Kelajakda','gray','lock')}</a>`).join('')}</div>`;}
  function stats(){const latest=new Map();state.checks.forEach(c=>latest.set(c.key,c));const all=[...latest.values()];return {count:all.length,accuracy:all.length?Math.round(all.reduce((a,c)=>a+c.score,0)/all.length):null,attempts:state.checks.length,all};}
  function activity(){const days=[];for(let n=6;n>=0;n--){const d=new Date();d.setDate(d.getDate()-n);const key=d.toDateString();days.push({label:['Yak','Du','Se','Chor','Pay','Ju','Sha'][d.getDay()],count:state.checks.filter(c=>new Date(c.at).toDateString()===key).length});}const max=Math.max(...days.map(d=>d.count),1);return `<div class="chart" aria-label="Oxirgi yetti kun mashqlari">${days.map(d=>`<div class="chart-day"><span class="chart-bar" title="${d.count} urinish"><i class="${d.count?'filled':''}" style="height:${d.count?Math.max(8,d.count/max*100)+'%':'4px'}"></i></span><span>${d.label}</span></div>`).join('')}</div>`;}
  function dashboard(){const s=stats(),last=state.last,m=last&&getMaterial(last.id)||published()[0];const sess=last&&m?session(m.id,last.mode):null;const gs=sess?groups(m,last.mode):[];const completed=sess?Object.keys(sess.results).length:0;const ratio=gs.length?Math.round(completed/gs.length*100):0;const start=m?(sess?`#practice/${m.id}/${last.mode}`:`#material/${m.id}`):'#library';
   return head('Xayrli kun, Abdulaziz','Tinglash ko‘nikmangizni birga rivojlantiramiz.','',`<span class="date">${new Date().getDate()+'-'+['yanvar','fevral','mart','aprel','may','iyun','iyul','avgust','sentabr','oktabr','noyabr','dekabr'][new Date().getMonth()]}</span>`)+`<div class="dashboard-top"><section class="card continue">${section(sess?'Qolgan joyingizdan davom eting':'Birinchi mashqingizni boshlang','#library/practice','Barchasi')}<div class="continue-body">${book()}<div class="continue-details"><span class="muted small">Listening Practice</span><h3>${esc(m?.title||'Yangi tinglash imkoniyatlari')}</h3><div class="meta"><span>${icon('file')}${sess?`${sess.index+1} / ${gs.length} segment`:'4 ta qisqa part'}</span><span>${icon('clock')}${m?Math.ceil(m.duration/1000)+' soniya':'Audio'}</span><span>${icon('chart')}${sess?names[last.mode]:'Bosqichma-bosqich'}</span></div><div class="progress-label">${sess?ratio+'% bajarildi':'Bir gapdan boshlang. O‘zingizga qulay ritmda.'}</div><div class="progress-track"><i style="width:${ratio}%"></i></div><div class="actions">${btn(sess?'Davom etish':'Practice boshlash',start)}<a class="link" href="#mistakes">${icon('pen')}Xatolarni ko‘rish</a></div></div>${wave()}</div></section><section class="card progress-card">${section('Sizning natijalaringiz')}<div class="chart-label"><span>7 kunlik faollik</span><small>Shu hafta</small></div>${activity()}<div class="stats-row"><div>${icon('target')}<span><strong>${s.accuracy===null?'—':s.accuracy+'%'}</strong><small>Javoblar aniqligi</small></span></div><div>${icon('file')}<span><strong>${s.count}</strong><small>Tekshirilgan segmentlar</small></span></div></div></section></div>${section('Qanday mashq qilamiz?','#library','Barcha materiallar')}<div class="practice-grid">${practiceTile('headphones','Listening Practice','Oson, o‘rta yoki murakkab. Tinglang, yozing va xatolaringizni ko‘ring.','Practice boshlash','#library/practice','teal')}${practiceTile('file','Listening Mock','Vaqt, savollar va bir martalik tinglash. Bilimingizni sinab ko‘ring.','Mock ishlash','#library/mock','orange')}${practiceTile('book','Transcript Study','Matn bilan birga tinglang. Biror gapni tanlab qayta eshiting.','Transkriptni ochish','#library/transcript','purple')}</div>${section('Kutubxonani ko‘rib chiqing','#library','Barcha materiallar')}<div class="library-grid">${['Kundalik ingliz tili','Akademik suhbatlar','Qo‘shimcha materiallar'].map((c,i)=>`<a class="card collection" href="#category/${encodeURIComponent(c)}"><div class="collection-art">${icon(i===2?'folder':'book')}</div><div><h3>${c}</h3><p>${['Hayotiy vaziyatlardan qisqa suhbatlar.','Universitet va ta’lim mavzulari.','Yangi tinglash imkoniyatlari.'][i]}</p><small>${published().filter(m=>m.category===c).length} ta material</small></div>${icon('chevron')}</a>`).join('')}</div><div class="daily"><strong>${icon('headphones')}KUNLIK ODAT</strong><span>Har kuni ozgina tinglash — katta o‘zgarishning boshlanishi.</span></div>`;}
  function practiceTile(i,title,text,label,to,color){return `<a class="practice-tile ${color}" href="${to}"><span class="tile-icon">${icon(i)}</span><div><h3>${title}</h3><p>${text}</p><span class="link">${label}${icon('chevron')}</span></div></a>`;}
  function materialCard(m,mode='practice'){return `<a class="card material-card" href="#material/${esc(m.id)}/${esc(mode)}"><div class="material-art">${book(true)}${badge('ORIGINAL DEMO')}<span class="art-play">${icon('play')}</span></div><div class="material-info"><span class="small muted">${esc(m.category)}</span><h3>${esc(m.title)}</h3><p>${esc(m.description)}</p><div class="material-bottom"><span>${icon('clock')}${Math.ceil(m.duration/1000)} soniya · ${m.parts.length} part</span><span>Mock + Practice ${icon('chevron')}</span></div></div></a>`;}
  function library(){const mode=routeInfo[1]||'practice';const category=routeInfo[0]==='category'?decodeURIComponent(routeInfo[1]||''):'';const search=routeInfo[0]==='search'?decodeURIComponent(routeInfo[1]||''):searchTerm;const items=published().filter(m=>(!category||m.category===category)&&(!libraryFilter||m.category===libraryFilter)&&(!search||norm(m.title+' '+m.description+' '+m.category).includes(norm(search))));const title=category||(mode==='mock'?'Listening Mock testlar':mode==='transcript'?'Transcript Library':'Practice Library');return head(title,'Bitta material. Mock va Practice uchun ikki xil imkoniyat.','TINGLASH KUTUBXONASI')+crumbs(null,title)+`<div class="card toolbar"><form id="library-search" class="toolbar-search">${icon('search')}<input name="search" aria-label="Kutubxonadan qidirish" placeholder="Material yoki mavzuni qidiring…" value="${esc(search)}"><button class="link" type="submit">Qidirish</button></form><select id="category-filter" aria-label="Kategoriyani tanlash"><option value="">Barcha kategoriyalar</option>${[...new Set(state.materials.map(m=>m.category).concat(['Akademik suhbatlar','Qo‘shimcha materiallar']))].map(c=>`<option ${c===libraryFilter?'selected':''} value="${esc(c)}">${esc(c)}</option>`).join('')}</select></div>${items.length?`<div class="result-count">${items.length} ta material · O‘quvchilar material qo‘sha olmaydi</div><div class="materials">${items.map(m=>materialCard(m,mode)).join('')}</div>`:empty('Bu yerda hozircha material yo‘q','Administrator nashr qilgan materiallar shu yerda paydo bo‘ladi.',btn('Kutubxonaga qaytish','#library','secondary','back'))}`;}
  function detail(){const m=getMaterial(routeInfo[1]);if(!m)return notFound();const mode=['practice','mock','transcript'].includes(routeInfo[2])?routeInfo[2]:'practice';return crumbs(m,'Rejim tanlash')+head(m.title,m.description,'LISTENING / MATERIAL')+`<div class="detail-grid"><section class="card detail-overview">${book()}<h3>${esc(m.category)}</h3><div class="meta"><span>${icon('clock')}${Math.ceil(m.duration/1000)} soniya</span><span>${icon('file')}${m.questions.length} savol</span></div><p>${esc(m.source)}<br>${esc(m.license)}</p></section><section class="card material-choices"><h2>Qaysi rejimda ishlaymiz?</h2><p class="mode-description">Material bir marta yuklangan. Practice sayt tomonidan avtomatik tayyorlangan.</p><div class="mode-tabs">${[['practice','headphones','Practice'],['mock','file','Mock test'],['transcript','book','Transkript']].map(([id,i,label])=>`<a class="${mode===id?'active':''}" href="#material/${esc(m.id)}/${id}">${icon(i)}${label}</a>`).join('')}</div>${mode==='practice'?`<p class="mode-description">O‘zingizga qulay darajani tanlang. Audio o‘zgarmaydi — faqat tinglash bo‘lagi farq qiladi.</p><div class="difficulty-grid">${['easy','medium','hard'].map((id,i)=>`<label class="difficulty-choice ${id==='easy'?'selected':''}"><input type="radio" name="difficulty" value="${id}" ${id==='easy'?'checked':''}><span><strong>${names[id]}</strong><small>${descriptions[id]}</small></span><span class="dot-level">${[0,1,2].map(n=>`<i class="${n>i?'off':''}"></i>`).join('')}</span></label>`).join('')}</div><button class="btn primary" data-action="start-practice" data-id="${esc(m.id)}">Practice boshlash${icon('chevron')}</button>`:mode==='mock'?`<div class="notice">${icon('clock')}<span><strong>Qisqa demo: ${m.questions.length} ta savol · 5 daqiqa.</strong><br>Har bir part audiosi bir marta tinglanadi. Topshirilguncha transkript va javoblar yashiriladi.</span></div><p class="mode-description">Bu to‘liq 40 savollik IELTS imtihoni emas. Mock va Practice orasidagi farqni ko‘rish uchun qisqa namuna.</p><div class="actions"><button class="btn primary" data-action="start-mock" data-id="${esc(m.id)}">Mock testni boshlash${icon('chevron')}</button></div>`:`<div class="notice">${icon('book')}<span>Matnni audio bilan birga o‘rganing. Har qanday gapni bosib, aynan o‘sha gapni tinglang.</span></div>${btn('Transcript Study ochish','#transcript/'+m.id)}`}</section></div>`;}
  function playerPanel(exam=false){return `<div class="audio-panel"><div class="audio-caption"><strong>${exam?'IMTIHON AUDIOSI':'TINGLANG VA DIQQAT QILING'}</strong><span>${exam?'Har part uchun bir marta':'Space — play / pause · R — qayta tinglash'}</span></div><div class="audio-controls">${!exam?`<button class="icon-btn" data-action="rewind" aria-label="5 soniya orqaga">${icon('rewind')}</button>`:''}<button class="play-btn" data-action="${exam?'exam-play':'audio-play'}" aria-label="${exam?'Part audiosini boshlash':'Audioni tinglash'}" disabled>${icon('play')}</button>${!exam?`<button class="icon-btn" data-action="forward" aria-label="5 soniya oldinga">${icon('forward')}</button>`:''}<div class="timeline"><input id="audio-seek" type="range" min="0" max="100" value="0" step=".01" aria-label="Audio vaqti" ${exam?'disabled':''}><div class="time-label"><span id="audio-current">0:00</span><span id="audio-total">0:00</span></div></div>${!exam?`<button class="icon-btn" data-action="replay" aria-label="Qayta tinglash">${icon('replay')}</button><select id="audio-speed" aria-label="Tinglash tezligi">${[.5,.75,1,1.25,1.5].map(n=>`<option value="${n}" ${n===1?'selected':''}>${n}×</option>`).join('')}</select>`:''}<label class="volume">${icon('volume')}<input id="audio-volume" type="range" min="0" max="1" step=".05" value="1" aria-label="Ovoz balandligi"></label></div></div>`;}
  function practice(){const m=getMaterial(routeInfo[1]);if(!m)return notFound();const mode=names[routeInfo[2]]?routeInfo[2]:'easy';const s=session(m.id,mode);const gs=groups(m,mode);if(routeInfo[3]!==undefined)s.index=Math.min(gs.length-1,Math.max(0,Number(routeInfo[3])||0));const g=gs[s.index];state.last={id:m.id,mode};save();const checked=Object.keys(s.results).length;return crumbs(m,'Practice / '+names[mode])+head(m.title,'Tinglang. Yozing. Har bir gap bilan oldinga qadam tashlang.','LISTENING / PRACTICE',badge(names[mode]+' rejim','','headphones'))+`<div class="workspace"><section class="card"><div class="panel-heading"><h2>${mode==='easy'?'Chunk':'Segment'} ${s.index+1}<small> / ${gs.length} · Part ${g.part}</small></h2><span class="saved" id="save-state">${icon('checks')}Saqlandi</span></div>${playerPanel()}<div class="answer-editor"><label class="answer-label" for="practice-answer">Nima eshitdingiz?</label><p class="muted">${mode==='easy'?'Qisqa bo‘lakni tinglang. Nechta so‘z kerakligini pastda ko‘rishingiz mumkin.':mode==='medium'?'Bitta to‘liq gapni tinglang va yozing. Xohlasangiz, qayta tinglang.':'Bir nechta gap uzluksiz yangraydi. Tinglab, yozib boring.'}</p>${mode==='easy'?`<div class="word-count" id="expected-word-count">${icon('file')}<strong>${words(g.text).length} ta so‘z</strong><small>Oson rejim yordamchisi</small></div><div class="word-dashes" aria-hidden="true">${words(g.text).map((_,i)=>`<span data-word="${i}"></span>`).join('')}</div>`:''}<textarea id="practice-answer" rows="6" spellcheck="false" placeholder="Eshitganingizni shu yerga yozing…">${esc(s.answers[s.index]||'')}</textarea><div class="editor-caption"><span>Javobingiz avtomatik saqlanadi</span><span id="answer-saved">Shu brauzerda</span></div><div class="actions"><button class="btn primary" data-action="check-answer">${icon('check')}Javobni tekshirish</button><button class="btn ghost" data-action="hint">${icon('light')}Yordam</button><button class="btn ghost" data-action="reveal">${icon('eye')}Transkript</button></div><div id="answer-hint"></div><div id="answer-feedback">${s.results[s.index]?comparison(s.results[s.index]):''}</div></div><div class="practice-nav"><button class="btn secondary" data-action="previous" ${s.index===0?'disabled':''}>${icon('back')}Oldingi segment</button><button class="btn primary" data-action="next">${s.index===gs.length-1?'Mashqni yakunlash':'Keyingi segment'}${icon('chevron')}</button></div></section><aside class="workspace-side"><section class="card"><h3>Sizning mashqingiz</h3><p class="muted">Har bir bo‘lak — kichik bir yutuq.</p><div class="progress-label">${checked} / ${gs.length} tekshirildi</div><div class="progress-track"><i style="width:${checked/gs.length*100}%"></i></div><div class="segment-buttons">${gs.map((_,i)=>`<button data-action="segment" data-index="${i}" class="${i===s.index?'current':''} ${s.results[i]?'done':''}" aria-label="${i+1}-segment">${s.results[i]?icon('check'):i+1}</button>`).join('')}</div><div class="quiet-box">${esc(descriptions[mode])}</div><div class="actions">${btn('Darajani almashtirish','#material/'+m.id,'secondary','settings')}</div></section><div class="side-tip">${icon('light')}<h3>Shoshilmang, tinglashni o‘rganing</h3><p>So‘zlarning bog‘lanishiga e’tibor bering. Avval sekinroq, keyin odatiy tezlikda eshiting.</p></div></aside></div>`;}
  function compare(reference,answer){const a=words(reference),b=words(answer),dp=Array.from({length:a.length+1},()=>Array(b.length+1).fill(0));for(let i=0;i<=a.length;i++)dp[i][0]=i;for(let j=0;j<=b.length;j++)dp[0][j]=j;for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++)dp[i][j]=Math.min(dp[i-1][j]+1,dp[i][j-1]+1,dp[i-1][j-1]+(a[i-1]!==b[j-1]));let i=a.length,j=b.length;const tokens=[];while(i||j){if(i&&j&&dp[i][j]===dp[i-1][j-1]+(a[i-1]!==b[j-1])){tokens.push({status:a[i-1]===b[j-1]?'correct':'incorrect',expected:a[--i],actual:b[--j]});}else if(i&&dp[i][j]===dp[i-1][j]+1)tokens.push({status:'missing',expected:a[--i],actual:''});else tokens.push({status:'extra',expected:'',actual:b[--j]});}tokens.reverse();return {score:Math.round(Math.max(0,1-dp[a.length][b.length]/Math.max(a.length,b.length,1))*100),tokens,reference,answer};}
  function comparison(result){const labels={correct:'To‘g‘ri',incorrect:'Xato',missing:'Yetishmaydi',extra:'Ortiqcha'};return `<div class="comparison"><div class="comparison-head"><strong>${result.score}% aniqlik</strong><span>${result.score===100?'Ajoyib! Har bir so‘z o‘z joyida.':'Yana bir bor tinglab ko‘ring.'}</span></div><div class="tokens">${result.tokens.map(t=>`<span class="token ${t.status}"><small>${labels[t.status]}</small>${t.status==='correct'?esc(t.actual):t.status==='missing'?`<ins>${esc(t.expected)}</ins>`:t.status==='extra'?`<del>${esc(t.actual)}</del>`:`<del>${esc(t.actual)}</del><ins>${esc(t.expected)}</ins>`}</span>`).join('')}</div><div class="reference"><small>Asl matn</small>${esc(result.reference)}</div></div><div class="actions"><button class="link" data-action="retry">${icon('replay')}Qayta urinib ko‘rish</button></div>`;}
  function transcript(){const m=getMaterial(routeInfo[1]);if(!m)return notFound();return crumbs(m,'Transcript Study')+head(m.title,'Gapni bosing va aynan o‘sha joyni qayta tinglang.','LISTENING / TRANSCRIPT STUDY')+`<section class="card">${playerPanel()}<div class="transcript-list">${m.sentences.map((s,i)=>`<button class="transcript-row" data-action="sentence" data-index="${i}"><span>${String(i+1).padStart(2,'0')}</span><div><small>Part ${s.part} · ${esc(m.parts[s.part-1])}</small><p>${esc(s.text)}</p></div><time>${fmt(s.start)}</time></button>`).join('')}</div></section>`;}
  function mistakes(){const all=stats().all.filter(c=>c.score<100).reverse();return head('Xatoni keyingi yutuqqa aylantiring','Qiyin bo‘lgan joyga qayting. Tinglang va yana urinib ko‘ring.','LISTENING / XATOLARIM')+(all.length?`<div class="review-list">${all.map(c=>`<section class="card review-card">${section(c.title,`#practice/${c.id}/${c.mode}/${c.index}`,'Yana mashq qilish')}<p class="muted">${names[c.mode]} · ${c.index+1}-segment · ${new Date(c.at).toLocaleDateString('uz-UZ')}</p>${comparison(c.result).replace(/<div class="actions">[\s\S]*$/,'')}</section>`).join('')}</div>`:empty('Hozircha xatolar yo‘q','Javobni tekshirganingizdan keyin, xato bo‘lgan segmentlar shu yerda ko‘rinadi.',btn('Practice boshlash','#library/practice')));}
  function progress(){const s=stats();const tests=Object.values(state.attempts).filter(a=>a.submitted);return head('Kichik qadamlar. Ko‘rinadigan natijalar.','Bu yerda faqat o‘zingiz bajargan demo mashqlarining natijalari bor.','SIZNING O‘QUV YO‘LINGIZ')+`<div class="stats-grid">${[['target',s.accuracy===null?'—':s.accuracy+'%','Practice aniqligi'],['file',s.count,'Tekshirilgan segment'],['headphones',s.attempts,'Jami urinishlar'],['chart',tests.length,'Topshirilgan mock']].map(([i,value,label])=>`<div class="card stat-card">${icon(i)}<strong>${value}</strong><span>${label}</span></div>`).join('')}</div><section class="card padded">${section('Bir haftalik tinglash')}<p class="muted">Har bir tekshirilgan javob — yana bir urinish.</p>${activity()}</section>${!s.count?`<div style="height:20px"></div>${empty('Birinchi qadamingizni kutyapmiz','Biror segmentni tinglab, javobni tekshiring. Natijalar shu yerda shakllanadi.',btn('Mashq tanlash','#library'))}`:''}${tests.length?`<div style="height:22px"></div><section class="card padded">${section('Mock natijalari')}${tests.map(a=>`<a class="result-line" href="#results/${esc(a.id)}">${icon('file')}<span>${esc(getMaterial(a.id)?.title||'Mock test')}<small>Qisqa demo natijasi</small></span><strong class="result-answer">${a.score} / ${a.total}</strong>${icon('chevron')}</a>`).join('')}</section>`:''}`;}
  function admin(){const total=state.materials.length,drafts=state.materials.filter(m=>m.status==='draft').length;return head('Yaxshi mashq bitta mock’dan boshlanadi','Mock yuklaysiz. Sayt undan Practice rejimlarini o‘zi tayyorlaydi.','ADMIN / KONTENT STUDIYASI',btn('Yangi mock','#admin/new','primary','plus'))+`<div class="notice good">${icon('spark')}<span><strong>Practice uchun alohida material yaratish shart emas.</strong><br>Mock’ning o‘sha audiosi va transkriptidan oson, o‘rta hamda murakkab mashqlar avtomatik yaratiladi.</span></div><div class="stats-grid">${[['file',total,'Jami mock material'],['shield',published().length,'Nashr qilingan'],['headphones',published().length*3,'Tayyor Practice rejimi'],['pen',drafts,'Qoralama material']].map(([i,value,label])=>`<div class="card stat-card">${icon(i)}<strong>${value}</strong><span>${label}</span></div>`).join('')}</div><div class="studio-grid"><section class="card"><div class="panel-heading"><h2>Mock materiallari</h2>${badge(total+' ta material')}</div>${state.materials.map(m=>`<a class="admin-material" href="#admin/review/${esc(m.id)}"><span class="file-icon">${icon('file')}</span><div><h3>${esc(m.title)}</h3><small>${esc(m.category)} · ${m.questions.length} savol · ${m.sentences.length} gap</small></div>${badge(m.status==='published'?'Mock + Practice tayyor':'Qoralama',m.status==='published'?'green':'amber')}${icon('chevron')}</a>`).join('')}</section><aside class="card padded"><h3>Bitta yuklash. Ikki imkoniyat.</h3><div class="flow-list">${[['1','Mock yuklang','Audio, savollar va mavjud transkript.'],['2','Sayt avtomatik ajratadi','Gaplar, chunklar va uchta qiyinlik darajasi.'],['3','Tekshiring va nashr qiling','O‘quvchi Mock yoki Practice’ni tanlaydi.']].map(([n,title,text])=>`<div class="flow-step"><span class="step-number">${n}</span><div><strong>${title}</strong><p>${text}</p></div></div>`).join('')}</div><div class="auto-box">${icon('spark')}Alohida Practice formasi va vaqtlarni qo‘lda kiritish yo‘q.</div><div class="admin-future"><div class="eyebrow">KELAJAKDA</div><div class="module-grid">${futureModules.map(([id,title,i])=>`<a class="card module future" href="#future/${id}">${icon(i)}<h3>${title}</h3>${badge('Hozircha yopiq','gray')}</a>`).join('')}</div></div></aside></div>`;}
  function wizard(stage){return `<div class="card wizard">${['Mock ma’lumotlari','Avtomatik tayyorlash','Tekshirish va nashr'].map((text,i)=>`<div class="${i<=stage?'active':''}"><span class="step-number">${i+1}</span>${text}${i<2?icon('chevron'):''}</div>`).join('')}</div>`;}
  function newMock(){const v=draftForm||{};return crumbs(null,'Admin / Yangi mock')+head('Mock’ni bir marta qo‘shing','Qolganini PracticeIELTS tayyorlaydi.','ADMIN / YANGI LISTENING MOCK')+wizard(0)+`<form class="card form-card" id="mock-form"><div id="form-error"></div><h2>Listening mock ma’lumotlari</h2><div class="form-grid"><label>Mock nomi<input name="title" maxlength="120" value="${esc(v.title||'')}" placeholder="Masalan: Listening Test 02" required></label><label>Kategoriya<input name="category" maxlength="100" value="${esc(v.category||'Kundalik ingliz tili')}" required></label><label class="full">Qisqa izoh<textarea name="description" rows="2" maxlength="500" placeholder="Bu material qanday mavzuda?">${esc(v.description||'')}</textarea></label><div class="full"><label>Mock audiosi</label><div class="upload-area">${icon('upload')}<div><strong>Bitta original audio fayl yuklang</strong><p>MP3, WAV, M4A yoki OGG · demo uchun 20 MB gacha.</p><input type="file" id="audio-upload" accept="audio/*" aria-label="Mock audio fayli"><p>Yoki tayyor original namunada oqimni ko‘ring:</p><button type="button" class="btn secondary" data-action="sample">${icon('headphones')}Demo audio va savollarni ishlatish</button></div></div><div id="upload-status" class="status-line">${uploadChoice?icon('check')+'Original demo audio tanlangan':''}</div></div><label class="full">Asl transkript<textarea name="transcript" id="transcript-input" rows="5" maxlength="20000" required placeholder="Audio matnini shu yerga joylang. Gaplarni saytning o‘zi ajratadi…">${esc(v.transcript||'')}</textarea><span class="muted" style="font-size:10px;font-weight:400;line-height:1.8">Bu HTML demo transkriptni o‘zi eshitib chiqarmaydi. Matn asosida gap/chunklarni avtomatik ajratadi; o‘zingiz yuklagan audio vaqtlari taxminiy bo‘ladi.</span></label><label class="full">Mock savollari va to‘g‘ri javoblar<textarea name="questions" id="questions-input" rows="4" maxlength="10000" required placeholder="Har qatorda: Savol | To‘g‘ri javob&#10;The tour begins at the central ____. | station">${esc(v.questions||'')}</textarea><span class="muted" style="font-size:10px;font-weight:400">Qisqa demo formati: har qatorda savol | javob. Namuna tugmasi bularni to‘ldiradi.</span></label><label>Manba / muallif<input name="source" value="${esc(v.source||'')}" required maxlength="200" placeholder="Masalan: O‘zim yozgan material"></label><label>Litsenziya / foydalanish huquqi<input name="license" value="${esc(v.license||'')}" required maxlength="200" placeholder="Masalan: Original, o‘zimga tegishli"></label><label class="checkbox full"><input type="checkbox" name="rights" ${v.rights?'checked':''} required>Men ushbu audio va matndan foydalanish huquqiga egaman.</label></div><div class="form-actions"><p>Vaqtlarni qo‘lda kiritishingiz shart emas.</p><button class="btn primary" type="submit">${icon('spark')}Mock + Practice tayyorlash</button></div></form>`;}
  function review(){const m=getMaterial(routeInfo[2]);if(!m)return notFound();return crumbs(m,'Admin / Ko‘rib chiqish')+head(m.title,'Mock va uchta Practice darajasi bitta materialdan tayyorlandi.','ADMIN / TEKSHIRISH',badge(m.status==='published'?'Nashr qilingan':'Ko‘rib chiqish','green','checks'))+wizard(2)+`${!m.knownTiming?`<div class="notice amber">${icon('info')}<span><strong>Demo chegarasi:</strong> gap va chunk vaqtlarining uzunligi matn uzunligi bo‘yicha taxminan hisoblangan. Bu haqiqiy forced alignment emas. Tayyor original namunada esa vaqtlar aniq.</span></div>`:''}<div class="preview-grid"><section class="card"><div class="panel-heading"><h2>Avtomatik tayyorlangan bo‘laklar</h2>${badge(m.sentences.length+' gap')}</div>${playerPanel()}<div class="transcript-list">${m.sentences.map((s,i)=>`<button class="transcript-row" data-action="sentence" data-index="${i}"><span>${String(i+1).padStart(2,'0')}</span><div><small>Part ${s.part} · ${fmt(s.start)} — ${fmt(s.end)}</small><p>${esc(s.text)}</p></div>${icon('play')}</button>`).join('')}</div></section><aside class="card preview-side"><h3>Practice avtomatik yaratildi</h3><div class="preview-counts">${['easy','medium','hard'].map(mode=>`<div><strong>${groups(m,mode).length}</strong><small>${names[mode]} bo‘laklari</small></div>`).join('')}</div><div class="flow-list">${[['check','Oson','Chunk / qisqa gap + so‘zlar soni.'],['check','O‘rta','Bitta gap. So‘zlar soni ko‘rinmaydi.'],['check','Murakkab','2–3 gap uzluksiz. So‘zlar soni yo‘q.']].map(([i,title,text])=>`<div class="flow-step"><span class="step-number">${icon(i)}</span><div><strong>${title}</strong><p>${text}</p></div></div>`).join('')}</div><div class="auto-box">${icon('spark')}Mock savollari ham, Practice ham bitta audiodan foydalanadi.</div>${m.status==='draft'?`<button class="btn primary wide" data-action="publish" data-id="${esc(m.id)}">${icon('shield')}Mock + Practice nashr qilish</button>`:btn('Materialni ochish','#material/'+m.id,'secondary','eye')}<p class="export-note">${m.status==='draft'?'Nashrdan so‘ng o‘quvchi ikkala rejimni ham ko‘radi.':'O‘quvchi ko‘rinishiga o‘tib, ikkala rejimni ham sinab ko‘ring.'}</p></aside></div>`;}
  function processing(){return head('Mock tayyorlanyapti','Bitta materialdan Mock va Practice imkoniyatlari.','ADMIN / AVTOMATIK TAYYORLASH')+wizard(1)+`<section class="card processing"><div class="spinner"></div><h2>Gaplar va chunklar ajratilmoqda</h2><p>Demo ichidagi matnni ajratish va audio chegaralarini tayyorlash.</p><div class="processing-list"><span>${icon('check')}Mock audio va savollari olindi</span><span>${icon('check')}Transkript gaplarga ajratildi</span><span>${icon('spark')}Oson · O‘rta · Murakkab tayyorlanmoqda</span></div></section>`;}
  function mock(){const m=getMaterial(routeInfo[1]);if(!m)return notFound();const a=state.attempts[m.id];if(!a){setTimeout(()=>navigate('material/'+m.id+'/mock'),0);return '';}if(a.submitted){setTimeout(()=>navigate('results/'+m.id),0);return '';}const part=Math.min(m.parts.length,Math.max(1,Number(routeInfo[2])||1));const qs=m.questions.map((q,i)=>({...q,index:i})).filter(q=>q.part===part);return crumbs(m,'Mock test')+head('Listening Mock · '+m.title,'Diqqat bilan tinglang. Javoblarni vaqt tugaguncha topshiring.','MOCK / QISQA DEMO',`<div class="exam-header"><span class="timer" id="exam-timer">${icon('clock')}<span>${fmt(Math.max(0,a.deadline-Date.now()))}</span></span><button class="btn primary" data-action="submit-mock">Testni topshirish${icon('check')}</button></div>`)+`<div class="notice amber">${icon('lock')}<span>Mock rejimida transkript, yordam va qayta tinglash yopiq. Har bir partni bir marta tinglang. ${m.questions.length} savollik qisqa demo.</span></div><div class="part-tabs">${m.parts.map((_,i)=>`<button data-action="exam-part" data-part="${i+1}" class="${i+1===part?'active':''}">Part ${i+1}</button>`).join('')}</div><section class="card"><div class="panel-heading"><h2>Part ${part} · ${esc(m.parts[part-1])}</h2>${badge(a.played[part]?'Tinglash boshlangan':'Bir martalik audio',a.played[part]?'gray':'','headphones')}</div>${playerPanel(true)}<div class="padded"><h3>Savollar</h3><p class="muted small" style="margin-top:6px">ONE WORD AND/OR A NUMBER · Javoblarni ingliz tilida yozing.</p>${qs.map(q=>`<div class="exam-question"><span class="question-number">${q.index+1}</span><div><p>${esc(q.prompt)}</p><input type="text" class="mock-answer" data-index="${q.index}" aria-label="${q.index+1}-savol javobi" maxlength="100" autocomplete="off" value="${esc(a.answers[q.index]||'')}" placeholder="Javobingiz"><div class="question-note">Javob avtomatik saqlanadi</div></div></div>`).join('')}</div></section><div class="actions" style="justify-content:space-between"><button class="btn secondary" data-action="exam-part" data-part="${part-1}" ${part===1?'disabled':''}>${icon('back')}Oldingi part</button><button class="btn primary" data-action="${part===m.parts.length?'submit-mock':'exam-part'}" data-part="${part+1}">${part===m.parts.length?'Testni topshirish':'Keyingi part'}${icon('chevron')}</button></div>`;}
  function results(){const m=getMaterial(routeInfo[1]),a=m&&state.attempts[m.id];if(!m||!a?.submitted)return notFound();return crumbs(m,'Mock natijasi')+head('Yaxshi urinish. Endi o‘rganish vaqti.','Mock’da qiyin bo‘lgan joylarni Practice’da qayta ishlang.','LISTENING / NATIJA')+`<section class="card padded"><div class="results-score"><div class="score-circle">${a.score}/${a.total}</div><div><h2>${Math.round(a.score/a.total*100)}% to‘g‘ri javob</h2><p>Bu ${a.total} savollik demo natijasi. IELTS band bahosi hisoblanmaydi.</p></div></div>${m.questions.map((q,i)=>{const correct=q.answers.some(answer=>norm(answer)===norm(a.answers[i]||''));return `<div class="result-line ${correct?'correct':'wrong'}">${icon(correct?'check':'close')}<span>${i+1}. ${esc(q.prompt)}<small>Siz: ${esc(a.answers[i]||'Javob yozilmagan')} · To‘g‘ri: ${esc(q.answers[0])}</small></span></div>`;}).join('')}<div class="actions">${btn('Practice’da ishlash','#material/'+m.id+'/practice')}${btn('Transkriptni o‘rganish','#transcript/'+m.id,'secondary','book')}<button class="btn ghost" data-action="restart-mock" data-id="${esc(m.id)}">${icon('replay')}Mock’ni qayta ishlash</button></div></section>`;}
  function future(){const m=futureModules.find(x=>x[0]===routeInfo[1]);if(!m)return notFound();return head(m[1],state.role==='admin'?'Bu modul uchun kontent qo‘shish keyinchalik ochiladi.':'Bu moduldan foydalanish keyinchalik ochiladi.','KELAJAK MODULI')+`<section class="card future-page empty"><span class="tile-icon">${icon(m[2])}</span>${badge('Kelajakda','gray','lock')}<h2>${m[1]} uchun ham joy bor.</h2><p>Hozir Listening’ni qulay va foydali qilishga e’tibor qaratyapmiz. ${state.role==='admin'?'Admin bu modulga hozircha material qo‘sha olmaydi.':'Bu modulga hozircha material qo‘shish yoki mashq ishlash mumkin emas.'}</p>${btn('Listening’ga qaytish',state.role==='admin'?'#admin':'#library','secondary','back')}</section>`;}
  function about(){return head('PracticeIELTS · Interfeys demo','Avval oqimni ko‘ramiz. Keyin haqiqiy platformaga ulaymiz.','DEMO HAQIDA')+`<section class="card padded" style="max-width:780px"><h2>Bu demoda nima ishlaydi?</h2><div class="flow-list">${[['1','Admin: mock bir marta qo‘shiladi','Audio, transkript va savollardan uchta Practice darajasi avtomatik hosil bo‘ladi.'],['2','O‘quvchi: material faqat ishlanadi','Mock, uchta Practice darajasi va transkriptni sinash mumkin. O‘quvchi kontent qo‘sha olmaydi.'],['3','Reading, Writing, Speaking — kelajakda','Admin va o‘quvchida ko‘rinadi, lekin material qo‘shish ham, mashq ishlash ham hali yo‘q.']].map(([n,title,text])=>`<div class="flow-step"><span class="step-number">${n}</span><div><strong>${title}</strong><p>${text}</p></div></div>`).join('')}</div><div class="notice amber">${icon('info')}<span>Bu faqat HTML/CSS/JS demo. Haqiqiy login, server yoki AI transkripsiya yo‘q. Admin/o‘quvchi tugmasi ko‘rinishlarni solishtirish uchundir. O‘zingiz yuklagan audio uchun vaqtlar taxminiy; original namunaning vaqtlarini aniq tayyorlaganmiz.</span></div><p class="small muted">Javoblar, natijalar va materiallar faqat shu brauzerda saqlanadi. Boshqa foydalanuvchiga yuborilmaydi. Namuna audiosi original matndan sun’iy ovoz bilan yaratilgan; Cambridge yoki boshqa mualliflik materiallari kiritilmagan.</p><div class="actions">${btn('O‘quvchi bosh sahifasi','#dashboard','secondary','home')}<button class="btn danger" data-action="reset-demo">Demo ma’lumotlarini tozalash</button></div></section>`;}
  function notFound(){return empty('Bu sahifa topilmadi','Bosh sahifaga qaytib, boshqa material tanlang.',btn('Bosh sahifa',state.role==='admin'?'#admin':'#dashboard','secondary','home'));}
  function navigate(path){const next='#'+path;if(location.hash===next)route();else location.hash=next;}
  function route(){
    audioVersion++;audio.pause();activeAudio=null;cancelAnimationFrame(audioFrame);clearInterval(timerInterval);clearTimeout(processingTimer);drawer=false;
    try{routeInfo=(location.hash.slice(1)||'dashboard').split('/');}catch{routeInfo=['dashboard'];}
    const page=routeInfo[0];
    if(state.role!=='admin'&&(page==='admin'||page==='processing')){navigate('dashboard');toast('Bu sahifa admin ko‘rinishiga tegishli.');return;}
    const views={dashboard,library,category:library,search:library,material:detail,practice,transcript,mistakes,progress,admin:()=>routeInfo[1]==='new'?newMock():routeInfo[1]==='review'?review():admin(),processing,mock,results,future,about};
    root.innerHTML=shell((views[page]||notFound)());window.scrollTo(0,0);
    if(page==='practice'){
      const m=getMaterial(routeInfo[1]);if(m){const mode=names[routeInfo[2]]?routeInfo[2]:'easy';const s=session(m.id,mode);updateDashes(s.answers[s.index]||'');prepareAudio(m,groups(m,mode)[s.index]);}
    }else if(page==='transcript'||(page==='admin'&&routeInfo[1]==='review')){
      const m=getMaterial(page==='transcript'?routeInfo[1]:routeInfo[2]);if(m)prepareAudio(m,page==='transcript'?{start:0,end:m.duration}:{...m.sentences[0]});
    }else if(page==='mock'){
      const m=getMaterial(routeInfo[1]),a=m&&state.attempts[m.id];if(m&&a&&!a.submitted){const part=Math.min(m.parts.length,Math.max(1,Number(routeInfo[2])||1));const segs=m.sentences.filter(s=>s.part===part);if(segs.length)prepareAudio(m,{start:segs[0].start,end:segs.at(-1).end},{exam:true,part});timerInterval=setInterval(()=>{const remaining=a.deadline-Date.now();const span=document.querySelector('#exam-timer span');if(span)span.textContent=fmt(Math.max(0,remaining));if(remaining<=0)submitMock(true);},400);}
    }else if(page==='processing'){processingTimer=setTimeout(()=>navigate('admin/review/'+routeInfo[1]),1400);}
  }
  async function audioDatabase(){return new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(new Error('Bu brauzerda fayl xotirasi ishlamayapti. Tayyor namunadan foydalaning.'));const req=indexedDB.open('practiceielts-demo-audio',1);req.onupgradeneeded=()=>req.result.createObjectStore('audio');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(new Error('Audio uchun brauzer xotirasini ochib bo‘lmadi. Tayyor namunani sinab ko‘ring.'));});}
  async function putAudio(id,file){const db=await audioDatabase();return new Promise((resolve,reject)=>{const tx=db.transaction('audio','readwrite');tx.objectStore('audio').put(file,id);tx.oncomplete=()=>{db.close();resolve();};tx.onerror=()=>{db.close();reject(new Error('Audio saqlanmadi. Brauzer xotirasini tekshiring.'));};});}
  async function getAudio(id){const db=await audioDatabase();return new Promise((resolve,reject)=>{const tx=db.transaction('audio','readonly');const req=tx.objectStore('audio').get(id);req.onsuccess=()=>{db.close();resolve(req.result);};req.onerror=()=>{db.close();reject(new Error('Audio topilmadi.'));};});}
  async function sourceFor(m){if(!m.audio.startsWith('indexeddb:'))return m.audio;if(sourceCache.has(m.id))return sourceCache.get(m.id);const file=await getAudio(m.id);if(!file)throw new Error('Audio bu brauzer xotirasida topilmadi. Tayyor namunani oching.');const url=URL.createObjectURL(file);sourceCache.set(m.id,url);return url;}
  async function prepareAudio(m,g,options={}){
    const version=++audioVersion;audio.pause();cancelAnimationFrame(audioFrame);
    activeAudio={m,g,options};const total=document.querySelector('#audio-total');if(total)total.textContent=fmt(g.end-g.start);
    const seek=document.querySelector('#audio-seek');if(seek){seek.max=(g.end-g.start)/1000;seek.value=0;}
    try{
      const src=await sourceFor(m);if(version!==audioVersion)return;
      const absolute=new URL(src,location.href).href;
      if(audio.src!==absolute){audio.src=src;audio.load();}
      if(audio.readyState<1)await new Promise((resolve,reject)=>{
        const timeout=setTimeout(()=>{cleanup();reject(new Error('Audio ochilmadi. ZIP’ni to‘liq ochib, index.html orqali kirganingizni tekshiring.'));},10000);
        const good=()=>{cleanup();resolve();};const bad=()=>{cleanup();reject(new Error('Audio faylini brauzer o‘qiy olmadi. MP3 yoki WAV sinab ko‘ring.'));};
        function cleanup(){clearTimeout(timeout);audio.removeEventListener('loadedmetadata',good);audio.removeEventListener('error',bad);}
        audio.addEventListener('loadedmetadata',good,{once:true});audio.addEventListener('error',bad,{once:true});
      });
      if(version!==audioVersion)return;
      audio.currentTime=g.start/1000;audio.playbackRate=Number(document.querySelector('#audio-speed')?.value||1);audio.volume=Number(document.querySelector('#audio-volume')?.value||1);
      const play=document.querySelector('.play-btn');if(play){play.disabled=!!(options.exam&&state.attempts[m.id]?.played[options.part]);play.innerHTML=icon('play');}
      updateAudioUI();if(options.auto)await audio.play();
    }catch(err){if(version===audioVersion)toast(err.message);}
  }
  function updateAudioUI(){if(!activeAudio)return;const {g,options}=activeAudio;const elapsed=Math.max(0,audio.currentTime*1000-g.start);const seek=document.querySelector('#audio-seek');const time=document.querySelector('#audio-current');if(seek)seek.value=elapsed/1000;if(time)time.textContent=fmt(elapsed);const play=document.querySelector('.play-btn');if(play&&!options.exam){play.innerHTML=icon(audio.paused?'play':'pause');play.setAttribute('aria-label',audio.paused?'Audioni tinglash':'Audioni to‘xtatish');}document.querySelectorAll('.transcript-row').forEach((row,i)=>{const s=activeAudio.m.sentences[i];row.classList.toggle('active',!!s&&audio.currentTime*1000>=s.start&&audio.currentTime*1000<s.end);});}
  audio.addEventListener('play',()=>{updateAudioUI();cancelAnimationFrame(audioFrame);function tick(){if(!activeAudio)return;const end=activeAudio.g.end/1000;if(audio.currentTime>=end){audio.pause();audio.currentTime=end;updateAudioUI();return;}updateAudioUI();audioFrame=requestAnimationFrame(tick);}audioFrame=requestAnimationFrame(tick);});
  audio.addEventListener('pause',()=>{cancelAnimationFrame(audioFrame);updateAudioUI();});
  audio.addEventListener('ended',()=>{cancelAnimationFrame(audioFrame);updateAudioUI();});
  function playAudio(replay=false){if(!activeAudio||activeAudio.options.exam)return;if(!replay&&!audio.paused){audio.pause();return;}const {g}=activeAudio;if(replay||audio.currentTime*1000>=g.end-50||audio.currentTime*1000<g.start)audio.currentTime=g.start/1000;audio.play().catch(()=>toast('Audioni boshlash uchun Play tugmasini yana bosing.'));}
  function currentPractice(){if(routeInfo[0]!=='practice')return null;const m=getMaterial(routeInfo[1]);if(!m)return null;const mode=names[routeInfo[2]]?routeInfo[2]:'easy';const s=session(m.id,mode);return {m,mode,s,gs:groups(m,mode)};}
  function saveAnswer(){const p=currentPractice(),input=document.querySelector('#practice-answer');if(!p||!input)return;p.s.answers[p.s.index]=input.value.slice(0,4000);save();updateDashes(input.value);}
  function updateDashes(answer){const count=words(answer).length;document.querySelectorAll('[data-word]').forEach(el=>el.classList.toggle('filled',Number(el.dataset.word)<count));}
  function movePractice(index){const p=currentPractice();if(!p)return;saveAnswer();if(index>=p.gs.length){navigate('progress');toast('Mashq saqlandi. Natijalaringizni ko‘ring.');return;}p.s.index=Math.max(0,index);save();navigate(`practice/${p.m.id}/${p.mode}/${p.s.index}`);}
  function checkAnswer(){const p=currentPractice(),input=document.querySelector('#practice-answer');if(!p||!input)return;if(!input.value.trim()){toast('Avval eshitganingizni yozing.');input.focus();return;}saveAnswer();const result=compare(p.gs[p.s.index].text,input.value);p.s.results[p.s.index]=result;state.checks.push({key:sid(p.m.id,p.mode)+'|'+p.s.index,id:p.m.id,mode:p.mode,index:p.s.index,title:p.m.title,score:result.score,result,at:new Date().toISOString()});save();document.querySelector('#answer-feedback').innerHTML=comparison(result);const oldScroll=scrollY;const gs=document.querySelector('.segment-buttons');if(gs){const b=gs.children[p.s.index];b.classList.add('done');b.innerHTML=icon('check');}const label=document.querySelector('.workspace-side .progress-label'),track=document.querySelector('.workspace-side .progress-track i');const done=Object.keys(p.s.results).length;if(label)label.textContent=`${done} / ${p.gs.length} tekshirildi`;if(track)track.style.width=done/p.gs.length*100+'%';window.scrollTo(0,oldScroll);}
  function startMock(id,restart=false){const m=getMaterial(id);if(!m)return;const prior=state.attempts[id];if(prior&&!prior.submitted&&!restart){navigate(`mock/${id}/1`);return;}if(prior?.submitted&&!restart){navigate('results/'+id);return;}state.attempts[id]={id,deadline:Date.now()+5*60*1000,answers:{},played:{},submitted:false};save();navigate(`mock/${id}/1`);}
  function submitMock(auto=false){const id=routeInfo[1],m=getMaterial(id),a=m&&state.attempts[id];if(!a||a.submitted)return;if(!auto&&!confirm('Mock testni topshirasizmi? Shundan so‘ng javoblar va transkript ochiladi.'))return;audio.pause();a.total=m.questions.length;a.score=m.questions.filter((q,i)=>q.answers.some(expected=>norm(expected)===norm(a.answers[i]||''))).length;a.submitted=true;a.submittedAt=new Date().toISOString();save();clearInterval(timerInterval);navigate('results/'+id);}
  function durationOf(file){return new Promise((resolve,reject)=>{const temp=new Audio(),url=URL.createObjectURL(file);const timeout=setTimeout(()=>{URL.revokeObjectURL(url);reject(new Error('Audio uzunligini o‘qib bo‘lmadi. MP3 yoki WAV faylni sinang.'));},12000);const finish=()=>{clearTimeout(timeout);URL.revokeObjectURL(url);};temp.onloadedmetadata=()=>{const ms=Math.round(temp.duration*1000);finish();if(!Number.isFinite(ms)||ms<=0)reject(new Error('Audio uzunligi aniqlanmadi.'));else resolve(ms);};temp.onerror=()=>{finish();reject(new Error('Bu fayl audio sifatida ochilmadi.'));};temp.src=url;});}
  function autoSegments(text,duration){let lines;if(typeof Intl.Segmenter==='function'){lines=Array.from(new Intl.Segmenter('en',{granularity:'sentence'}).segment(text),x=>x.segment.trim()).filter(Boolean);}else lines=text.match(/[^.!?]+[.!?]*/g)?.map(s=>s.trim()).filter(Boolean)||[];if(!lines.length)throw new Error('Transkript matnini kiriting.');const rawChunks=[],sentences=[],chunks=[];const total=lines.reduce((sum,t)=>sum+words(t).length,0);if(!total)throw new Error('Transkriptda so‘z topilmadi.');let count=0;for(const line of lines){const list=line.split(/\s+/).filter(Boolean);const start=Math.round(count/total*duration);const first=chunks.length;for(let i=0;i<list.length;i+=6){let slice=list.slice(i,i+6);if(list.length-i===7)slice=list.slice(i);const chunkStart=Math.round(count/total*duration);count+=slice.length;chunks.push({part:1,text:slice.join(' '),start:chunkStart,end:Math.min(duration,Math.round(count/total*duration))});if(list.length-i===7)break;}sentences.push({part:1,text:line,start,end:chunks.at(-1).end,chunkStart:first,chunkEnd:chunks.length});}if(chunks.length)chunks.at(-1).end=duration;if(sentences.length)sentences.at(-1).end=duration;return {chunks,sentences};}
  async function createMock(form){const button=form.querySelector('button[type="submit"]');button.disabled=true;const error=document.querySelector('#form-error');error.innerHTML='';try{const data=Object.fromEntries(new FormData(form));draftForm=data;if(!uploadChoice)throw new Error('Audio faylini tanlang yoki original demo namunasini ishlating.');const questionLines=String(data.questions||'').split('\n').map(line=>line.trim()).filter(Boolean);if(!questionLines.length)throw new Error('Kamida bitta savol kiriting.');if(questionLines.length>40)throw new Error('Demo uchun 40 tagacha savol kiriting.');const questions=questionLines.map((line,i)=>{const [prompt,...answers]=line.split('|').map(x=>x.trim());if(!prompt||!answers.filter(Boolean).length)throw new Error(`${i+1}-savolda “Savol | javob” formatidan foydalaning.`);return {prompt,answers:answers.filter(Boolean),part:1};});const id='local-'+Date.now().toString(36);let model;if(uploadChoice.type==='sample'){const original=window.DEMO_MATERIAL;const sameText=norm(data.transcript)===norm(original.sentences.map(s=>s.text).join('\n'));model={...(sameText?structuredClone(original):autoSegments(data.transcript,original.duration)),audio:original.audio,duration:original.duration,parts:sameText?[...original.parts]:['Listening section'],knownTiming:sameText};if(sameText)questions.forEach((q,i)=>q.part=Math.min(4,Math.floor(i/questions.length*4)+1));}else{const file=uploadChoice.file;if(file.size>20*1024*1024)throw new Error('Demo uchun audio 20 MB dan kichik bo‘lsin.');if(!/\.(mp3|wav|m4a|ogg|aac|flac)$/i.test(file.name))throw new Error('MP3, WAV, M4A, OGG, AAC yoki FLAC audio tanlang.');const duration=await durationOf(file);const segments=autoSegments(data.transcript,duration);await putAudio(id,file);model={...segments,audio:'indexeddb:'+id,duration,parts:['Listening section'],knownTiming:false};}model={...model,id,title:String(data.title).trim(),description:String(data.description||'Mock va undan avtomatik yaratilgan Practice.'),category:String(data.category).trim(),source:String(data.source).trim(),license:String(data.license).trim(),questions,status:'draft'};if(!model.title||!model.category||!model.source||!model.license||!data.rights)throw new Error('Mock nomi, kategoriya, manba va foydalanish huquqini to‘ldiring.');state.materials.push(model);save();uploadChoice=null;draftForm=null;navigate('processing/'+id);}catch(err){error.innerHTML=`<div class="error-message" role="alert">${esc(err.message)}</div>`;error.scrollIntoView({block:'center',behavior:'smooth'});}finally{button.disabled=false;}}
  root.addEventListener('click',async event=>{
    const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action;
    if(action==='drawer'){drawer=!drawer;const sidebar=document.querySelector('.sidebar');sidebar.classList.toggle('open',drawer);if(drawer){const bg=document.createElement('button');bg.className='backdrop';bg.dataset.action='drawer';bg.setAttribute('aria-label','Menyuni yopish');root.appendChild(bg);}else document.querySelector('.backdrop')?.remove();return;}
    if(action==='role'){saveAnswer();state.role=button.dataset.role;save();navigate(state.role==='admin'?'admin':'dashboard');return;}
    if(action==='audio-play')playAudio();
    if(action==='replay')playAudio(true);
    if(action==='rewind'||action==='forward'){if(activeAudio&&!activeAudio.options.exam){const {g}=activeAudio;audio.currentTime=Math.max(g.start/1000,Math.min(g.end/1000,audio.currentTime+(action==='rewind'?-5:5)));updateAudioUI();}}
    if(action==='start-practice'){const mode=document.querySelector('input[name="difficulty"]:checked')?.value||'easy';navigate(`practice/${button.dataset.id}/${mode}`);}
    if(action==='check-answer')checkAnswer();
    if(action==='previous'){const p=currentPractice();if(p)movePractice(p.s.index-1);}
    if(action==='next'){const p=currentPractice();if(p)movePractice(p.s.index+1);}
    if(action==='segment')movePractice(Number(button.dataset.index));
    if(action==='hint'||action==='reveal'){const p=currentPractice();if(!p)return;const text=p.gs[p.s.index].text;document.querySelector('#answer-hint').innerHTML=`<div class="hint">${esc(action==='reveal'?text:text.split(/\s+/).map(w=>w[0]+'＿'.repeat(Math.min(w.length-1,7))).join(' '))}</div>`;}
    if(action==='retry'){const input=document.querySelector('#practice-answer');if(input){input.value='';saveAnswer();document.querySelector('#answer-feedback').innerHTML='';document.querySelector('#answer-hint').innerHTML='';input.focus();}}
    if(action==='sentence'){const m=getMaterial(routeInfo[0]==='admin'?routeInfo[2]:routeInfo[1]);if(m)prepareAudio(m,m.sentences[Number(button.dataset.index)],{auto:true});}
    if(action==='sample'){uploadChoice={type:'sample'};const m=window.DEMO_MATERIAL;const form=document.querySelector('#mock-form');form.elements.title.value='Everyday English · Listening Test '+String(state.materials.length+1).padStart(2,'0');form.elements.category.value=m.category;form.elements.description.value=m.description;form.elements.transcript.value=m.sentences.map(s=>s.text).join('\n');form.elements.questions.value=m.questions.map(q=>q.prompt+' | '+q.answers.join(' | ')).join('\n');form.elements.source.value=m.source;form.elements.license.value=m.license;form.elements.rights.checked=true;document.querySelector('#audio-upload').value='';document.querySelector('#upload-status').innerHTML=icon('check')+'Original demo audio tanlandi · '+fmt(m.duration)+' · transkript va savollar to‘ldirildi';toast('Namuna tayyor. “Mock + Practice tayyorlash” tugmasini bosing.');}
    if(action==='publish'){if(state.role!=='admin')return;const m=getMaterial(button.dataset.id);if(m){m.status='published';save();route();toast('Mock va uchta Practice rejimi birga nashr qilindi.');}}
    if(action==='start-mock')startMock(button.dataset.id);
    if(action==='restart-mock'){if(confirm('Yangi mock urinishini boshlaysizmi? Avvalgi demo natijasi almashtiriladi.'))startMock(button.dataset.id,true);}
    if(action==='exam-part'){const m=getMaterial(routeInfo[1]);if(m)navigate(`mock/${m.id}/${Math.min(m.parts.length,Math.max(1,Number(button.dataset.part)))}`);}
    if(action==='exam-play'){if(!activeAudio?.options.exam)return;const {m,options}=activeAudio,a=state.attempts[m.id];if(a.played[options.part])return;try{await audio.play();a.played[options.part]=true;save();button.disabled=true;const badgeEl=document.querySelector('.panel-heading .badge');if(badgeEl)badgeEl.textContent='Bir marta tinglash boshlandi';}catch{toast('Play tugmasini qayta bosing.');}}
    if(action==='submit-mock')submitMock();
    if(action==='reset-demo'){if(confirm('Faqat shu brauzerdagi demo materiallar, javoblar va natijalar tozalansinmi?')){state=initial();save();try{indexedDB.deleteDatabase('practiceielts-demo-audio');}catch{}sourceCache.forEach(src=>URL.revokeObjectURL(src));sourceCache.clear();navigate('dashboard');toast('Demo boshlang‘ich holatga qaytdi.');}}
  });
  root.addEventListener('input',event=>{
    const el=event.target;
    if(el.id==='practice-answer'){saveAnswer();document.querySelector('#answer-feedback').innerHTML='';}
    if(el.classList.contains('mock-answer')){const a=state.attempts[routeInfo[1]];if(a&&!a.submitted){a.answers[el.dataset.index]=el.value;save();}}
    if(el.id==='audio-seek'&&activeAudio&&!activeAudio.options.exam){audio.currentTime=activeAudio.g.start/1000+Number(el.value);updateAudioUI();}
    if(el.id==='audio-volume')audio.volume=Number(el.value);
  });
  root.addEventListener('change',event=>{
    const el=event.target;
    if(el.name==='difficulty')document.querySelectorAll('.difficulty-choice').forEach(choice=>choice.classList.toggle('selected',!!choice.querySelector('input:checked')));
    if(el.id==='audio-speed'&&activeAudio&&!activeAudio.options.exam)audio.playbackRate=Number(el.value);
    if(el.id==='category-filter'){libraryFilter=el.value;route();}
    if(el.id==='audio-upload'&&el.files[0]){uploadChoice={type:'file',file:el.files[0]};const status=document.querySelector('#upload-status');status.textContent=el.files[0].name+' · '+(el.files[0].size/1024/1024).toFixed(2)+' MB';}
  });
  root.addEventListener('submit',event=>{event.preventDefault();const form=event.target;if(form.id==='global-search'||form.id==='library-search'){searchTerm=String(new FormData(form).get('search')||'').trim();navigate('search/'+encodeURIComponent(searchTerm));}if(form.id==='mock-form')createMock(form);});
  document.addEventListener('keydown',event=>{if(event.target.closest('input,textarea,select,button,a,[contenteditable="true"]'))return;if(routeInfo[0]==='practice'||routeInfo[0]==='transcript'){if(event.code==='Space'){event.preventDefault();playAudio();}if(event.key.toLowerCase()==='r'){event.preventDefault();playAudio(true);}}});
  window.addEventListener('hashchange',route);
  if(!location.hash)history.replaceState(null,'','#dashboard');
  route();
})();
